function categorize(sys, dia){
  if(!(sys > 0 && dia > 0)) return null;
  if(sys > 180 || dia > 120) return {category:'高血压危象', en:'Hypertensive Crisis', level:4};
  if(sys >= 140 || dia >= 90) return {category:'2 级高血压', en:'Stage 2 Hypertension', level:3};
  if(sys >= 130 || dia >= 80) return {category:'1 级高血压', en:'Stage 1 Hypertension', level:2};
  if(sys >= 120 && dia < 80) return {category:'血压升高', en:'Elevated', level:1};
  return {category:'正常', en:'Normal', level:0};
}
var EXPORTS = { categorize:categorize };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BloodPressureForgePure = EXPORTS; }
